    public BloodSwordThrustSlashModel(ModelPart root) {
        super(root);
    }

    @Override
    public ModelLayerLocation getModelTexture() {
        return BLOOD_SWORD_THRUST_TEXTURE[TEXTURE_ARR_SIZE_M1];
    }

    @Override
    public ModelLayerLocation getModelTextureByArrayIndex(int index) {
        return BLOOD_SWORD_THRUST_TEXTURE[ExtraMathMethods.clamp(index, 0, TEXTURE_ARR_SIZE_M1)];
    }

    @Override
    public float getScale() { return 1.5f; }

